insert into public.passages (id, source_id, ordinal, content, page_number, embedding) values ('00000000-0000-4000-8100-000000000002', '00000000-0000-4000-8000-000000000031', 1, 'The AI RMF Core provides outcomes and actions that enable dialogue, understanding, and activities to manage AI risks and responsibly develop trustworthy AI systems. The Core is composed of four functions: GOVERN, MAP, MEASURE, and MANAGE. Governance is designed to be a cross-cutting function to inform and be infused throughout the other three functions. Risk management should be continuous, timely, and performed throughout the AI system lifecycle dimensions.', 20, '[0.008584896102547646,-0.08010596036911011,-0.06410743296146393,-0.04049885272979736,0.13464239239692688,0.03477448970079422,0.0250487569719553,0.058538757264614105,0.016635553911328316,0.09905949234962463,-0.02933729812502861,-0.04706345498561859,0.07088257372379303,0.016080282628536224,-0.003976274747401476,0.029318027198314667,-0.05525246635079384,-0.03114539012312889,-0.06396114826202393,-0.004673832096159458,0.00904220063239336,0.01965167000889778,-0.0520327091217041,-0.03958087041974068,-0.10496335476636887,0.002757628681138158,-0.03582415357232094,-0.054450441151857376,-0.0662386417388916,-0.025694049894809723,0.06609360128641129,-0.027854667976498604,0.08791095018386841,0.002157012466341257,-0.01696629263460636,0.08903522789478302,-0.04490208625793457,-0.06131863594055176,0.02953314036130905,-0.04873546212911606,-0.05281827598810196,-0.04321063309907913,0.03221489489078522,-0.05174127221107483,0.04491226375102997,0.06828015297651291,-0.005614688619971275,-0.05002429708838463,0.0430990606546402,-0.015584015287458897,-0.08936525881290436,-0.022820627316832542,-0.019200211390852928,-0.018358277156949043,0.05050479993224144,0.06000534072518349,-0.002089044312015176,-0.039637938141822815,-0.039413534104824066,-0.05943610146641731,0.051911551505327225,-0.04555701091885567,0.053188078105449677,0.012328101322054863,0.1124922186136