insert into public.sources (id, notebook_id, title, kind, original_url, attribution, license_name, license_url, content, processing_stage, embedding_model, embedding_dimensions) values ('00000000-0000-4000-8000-000000000032', '00000000-0000-4000-8000-000000000003', 'Artificial Intelligence Risk Management Framework: Generative AI Profile', 'pdf', 'https://doi.org/10.6028/NIST.AI.600-1', 'Chloe Autio, Reva Schwartz, Jesse Dunietz, Shomik Jain, Martin Stanley, Elham Tabassi, Patrick Hall, and Kamie Roberts (2024), NIST AI 600-1. Republished courtesy of the National Institute of Standards and Technology.', 'NIST Technical Series reuse terms', 'https://www.nist.gov/open/copyright-fair-use-and-licensing-statements-srd-data-software-and-technical-series-publications', '[PDF page 6]
Confabulation refers to a phenomenon in which generative AI systems generate and confidently present erroneous or false content in response to prompts. Confabulations can include outputs that diverge from the prompt or contradict earlier statements. Risks arise when users believe false content because of the confident nature of the response. Generated logic or citations that purport to justify an answer may further mislead people into inappropriately trusting the system’s output.

[PDF page 24]
Establish known assumptions and practices for determining data origin and content lineage for documentation and evaluation. Institute test and evaluation for data and content flows within the generative AI system, including original data sources, data transformations, and decision-making criteria. Identify and document how the system relies on upstream data sources, including content provenance, and whether it serves as an upstream dependency for other systems.

[PDF page 25]
Deploy and document fact-checking techniques to verify the accuracy and veracity of information generated by generative AI systems, especially when information comes from multiple or unknown sources. Implement plans for regular adversarial testing to identify vulnerabilities and potential manipulation or misuse. Involve end users, practitioners, and operators in prototyping and testing, covering scenarios such as crisis situations or ethically sensitive contexts.', 'ready', 'all-MiniLM-L6-v2', 384) on conflict (id) do update set title = excluded.title, original_url = excluded.original_url, attribution = excluded.attribution, license_name = excluded.license_name, license_url = excluded.license_url, content = excluded.content, processing_stage = excluded.processing_stage, embedding_model = excluded.embedding_model, embedding_dimensions = excluded.embedding_dimensions;

insert into public.passages (id, source_id, ordinal, content, page_number, embedding) values ('00000000-0000-4000-8200-000000000001', '00000000-0000-4000-8000-000000000032', 0, 'Confabulation refers to a phenomenon in which generative AI systems generate and confidently present erroneous or false content in response to prompts. Confabulations can include outputs that diverge from the prompt or contradict earlier statements. Risks arise when users believe false content because of the confident nature of the response. Generated logic or citations that purport to justify an answer may further mislead people into inappropriately trusting the system’s output.', 6, '[0.014530685730278492,0.02073424495756626,0.0030329395085573196,0.04899386689066887,0.03424285724759102,-0.03447043523192406,0.03520519286394119,0.05619509518146515,0.05401014909148216,-0.03301949426531792,0.00723401689901948,-0.023465007543563843,0.12232434749603271,-0.10010512173175812,-0.10867452621459961,-0.03323572501540184,0.01377157960087061,-0.032102879136800766,-0.022497737780213356,0.014016100205481052,0.0024720386136323214,0.024688778445124626,-0.06471723318099976,0.040518105030059814,0.00446351757273078,0.030245985835790634,-0.04908465966582298,-0.04051787033677101,0.05416308343410492,0.003559079486876726,-0.012909029610455036,0.14548523724079132,-0.051332782953977585,-0.0030817589722573757,0.005049907136708498,0.06342790275812149,-0.020666852593421936,0.049482978880405426,0.07537508010864258,-0.04510478675365448,-0.00943850539624691,-0.032219406217336655,0.008131931535899639,-0.027950195595622063,0.001588067738339305,0.006032579578459263,-0.040414776653051376,0.013659621588885784,0.0020125005394220352,0.00400143675506115,-0.07720120251178741,-0.018009569495916367,0.06425058841705322,-0.008468425832688808,-0.05032956227660179,0.018173374235630035,0.04034922271966934,0.07248002290725708,-0.05459572747349739,0.02598288655281067,0.002372437622398138,-0.029729921370744705,-0.05898439139127731,0.0057213