insert into public.passages (id, source_id, ordinal, content, page_number, embedding) values ('00000000-0000-4000-8200-000000000002', '00000000-0000-4000-8000-000000000032', 1, 'Establish known assumptions and practices for determining data origin and content lineage for documentation and evaluation. Institute test and evaluation for data and content flows within the generative AI system, including original data sources, data transformations, and decision-making criteria. Identify and document how the system relies on upstream data sources, including content provenance, and whether it serves as an upstream dependency for other systems.', 24, '[-0.0722450241446495,0.018540170043706894,0.008208404295146465,-0.015368161723017693,0.05211171880364418,-0.016233233734965324,-0.08129437267780304,0.004285449627786875,-0.009660127572715282,0.0724574625492096,-0.0448724702000618,-0.05621248483657837,0.0896996408700943,0.01913071796298027,-0.04181628301739693,0.05185886099934578,0.08048535138368607,-0.010595862753689289,0.013184540905058384,-0.05108361691236496,0.02963363751769066,0.08939318358898163,-0.04245287552475929,-0.03181932866573334,0.03154091536998749,0.09479495137929916,-0.026521064341068268,-0.044803716242313385,0.11388424783945084,-0.07160108536481857,0.049687709659338,0.08332929015159607,0.0066794040612876415,0.04152907058596611,-0.03094485029578209,0.0975959524512291,0.02495400421321392,0.0006547091179527342,0.07461623847484589,0.053389497101306915,0.04346398264169693,-0.05851958319544792,-0.02345365658402443,-0.04656025767326355,0.07942374050617218,0.03481721132993698,-0.030118390917778015,0.0036669946275651455,-0.04527101293206215,0.06643352657556534,-0.11477828770875931,-0.030968813225626945,-0.0014498524833470583,0.07312529534101486,-0.04208993911743164,0.03757409006357193,0.09050872921943665,-0.01651247963309288,-0.02883915789425373,0.044459208846092224,0.021090295165777206,-0.037299104034900665,-0.003414178267121315,-0.027057236060500145,0.06146152317523956